'use strict';
const OPT_DECISIONS=[
{id:'lag',title:P('Recent data ka trap','The recent-data trap'),evidence:P('Pichlay complete period ka CPA Rs 900 hai. Kal ka CPA Rs 2,000 dikhta hai, lekin typical conversion delay 10 din hai. Page/measurement fault ki evidence nahi.','The mature period has CPA Rs 900. Yesterday shows CPA Rs 2,000, but typical conversion delay is 10 days. No page or measurement fault has been established.'),question:P('Abhi kaunsi inference sahi hai?','Which inference is justified now?'),options:[P('Performance definitely aadhi ho gayi','Performance has definitely halved'),P('Recent results incomplete hain; mature periods aur urgent faults separately review karo','Recent results are incomplete; review mature periods and urgent faults separately'),P('Kal ki sab clicks ko conversions bana do','Turn yesterday’s clicks into conversions')],answer:1,why:P('Spend jaldi report hota hai, conversions baad mein aa sakti hain. Iska matlab har loss ko delay keh kar ignore karna bhi nahi.','Spend can be recorded before delayed conversions arrive. This does not justify dismissing every loss as delay.'),source:['lag']},
{id:'quality',title:P('Cheap lead ya useful lead?','Cheap lead or useful lead?'),evidence:P('A: spend Rs 10,000 → 40 forms → 4 qualified. B: spend Rs 10,000 → 20 forms → 10 qualified. Dono periods mature hain aur qualification rule same hai.','A: Rs 10,000 → 40 forms → four qualified. B: Rs 10,000 → 20 forms → ten qualified. Both periods are mature and use the same qualification rule.'),question:P('Qualified lead cost kis mein behtar hai?','Which has the better qualified-lead cost?'),options:[P('B: Rs 1,000 vs A: Rs 2,500; won sales aur margins bhi review karo','B: Rs 1,000 versus A: Rs 2,500; also review won sales and margins'),P('A, kyun ke forms zyada hain','A, because it has more forms'),P('Dono mein exactly same business result hai','Both have exactly the same business outcome')],answer:0,why:P('Raw CPL A mein Rs 250, B mein Rs 500 hai; qualified CPL ka conclusion ulta hai. Customer economics tak funnel follow karo.','Raw CPL is Rs 250 for A and Rs 500 for B, but qualified CPL reverses the conclusion. Follow the funnel through customer economics.'),source:['offline']},
{id:'mix',title:P('Average se dhoka','The blended-average trap'),evidence:P('Total CPA better hui. Saath hi brand traffic ka share barha; non-brand CPA same hai. Koi controlled experiment nahi hua.','Overall CPA improved while the brand share increased. Non-brand CPA is unchanged. There was no controlled experiment.'),question:P('Kya prove hua?','What has been established?'),options:[P('Har non-brand change successful prove hui','Every non-brand change was proven successful'),P('Budget double karna hamesha safe hai','Doubling the budget is always safe'),P('Blended result improve hua; mix change aur segment performance alag inspect karo','The blended result improved; inspect mix changes and segment performance separately')],answer:2,why:P('Sasti brand demand ka zyada share average ko improve kar sakta hai. Before/after comparison akela causal uplift ki proof nahi.','A larger share of cheaper brand demand can improve the average. A before/after comparison alone does not establish causal uplift.'),source:['experimentspage','terms']},
{id:'small',title:P('2 vs 3 sales','Two versus three sales'),evidence:P('Same spend par A ke 2 aur B ke 3 sales hain. Test abhi chhota hai; confidence/effect interval aur conversion delay review nahi hua.','At the same spend, A has two sales and B has three. The test is small; uncertainty and conversion delay have not been reviewed.'),question:P('Kya B guaranteed winner hai?','Is B a guaranteed winner?'),options:[P('Haan, 50% uplift hamesha conclusive hai','Yes, a 50% observed uplift is always conclusive'),P('Nahi; observed difference hai, uncertainty, lag aur pre-defined evidence rule review karo','No; it is an observed difference. Review uncertainty, lag and the pre-defined evidence rule'),P('A ka result delete kar do','Delete A’s result')],answer:1,why:P('Chhoti counts mein ek sale percentage ko bohat change kar deti hai. Ye app statistical significance calculate ya certify nahi karti.','One sale can greatly change a percentage when counts are small. This app does not calculate or certify statistical significance.'),source:['experimentspage']},
{id:'test',title:P('Kya test karna hai?','What are you testing?'),evidence:P('Hypothesis: shorter booking form qualified enquiries barhaye ga. Team ek saath form, keywords, ads, bidding aur locations change karna chahti hai.','Hypothesis: a shorter booking form will improve qualified enquiries. The team wants to change the form, keywords, ads, bidding and locations together.'),question:P('Interpretation ko clear kaise rakho?','How can you keep the result interpretable?'),options:[P('Defined form change test karo; other conditions/changes record aur primary metric/guardrails pehle decide karo','Test the defined form change; record other conditions/changes and predefine the primary metric/guardrails'),P('Sab change karo aur result form ko credit do','Change everything and credit the form'),P('Sirf CTR ko qualified enquiries keh do','Call CTR qualified enquiries')],answer:0,why:P('Single hypothesis ka matlab customer safety fixes rokna nahi. Concurrent changes ko log karo; contamination se causal interpretation limited ho sakti hai.','A single hypothesis does not mean delaying urgent fixes. Log concurrent changes; contamination can limit causal interpretation.'),source:['experimentspage']},
{id:'marginal',title:P('Scale karne ka hidden loss','The hidden loss when scaling'),evidence:P('Existing contribution after ads +Rs 20,000 hai. Extra Rs 10,000 spend se estimated customer contribution sirf Rs 8,000 hai; ye uncertain model hai.','Existing contribution after ads is +Rs 20,000. An extra Rs 10,000 spend models only Rs 8,000 in added customer contribution; this is uncertain.'),question:P('Additional spend ka modeled result?','What is the modeled result of the additional spend?'),options:[P('Automatically +Rs 20,000','Automatically +Rs 20,000'),P('Har extra click profitable hai','Every extra click is profitable'),P('Extra contribution after ads −Rs 2,000; total profitable rehnay se extra spend profitable prove nahi hota','Added contribution after ads is −Rs 2,000; a profitable total does not prove profitable added spend')],answer:2,why:P('8,000 − 10,000 = −2,000. Average aur marginal result alag hain. Model assumptions ko real incremental evidence se validate karo.','8,000 − 10,000 = −2,000. Average and marginal outcomes differ. Validate assumptions using real incremental evidence.'),source:['bidtargets','measurement']}
];
const SCALE_FIELDS=['spend','cpc','cvr','close','aov','margin','capacity'];
const TEST_FIELDS=['hypothesis','change','primary','guardrail','evidence','lagDays','readoutDays','split','rollback','owner'];
let optTab='decisions',optDecision=0;
function cleanOptimization(value){const result={};if(!value||typeof value!=='object')return result;for(const b of BUSINESSES){const x=value[b.id];if(!x||typeof x!=='object')continue;const r={answers:{},scale:{},plan:{}};for(const d of OPT_DECISIONS)if(Number.isInteger(x.answers?.[d.id])&&x.answers[d.id]>=0&&x.answers[d.id]<d.options.length)r.answers[d.id]=x.answers[d.id];for(const [key,fields]of [['scale',SCALE_FIELDS],['plan',TEST_FIELDS]])for(const field of fields)if(typeof x[key]?.[field]==='string')r[key][field]=x[key][field].slice(0,key==='scale'?50:5000);result[b.id]=r;}return result;}
function optimizationRecord(){return state.optimization[state.business]||(state.optimization[state.business]={answers:{},scale:{},plan:{}});}
function optimizationSolved(){const r=optimizationRecord();return OPT_DECISIONS.filter(d=>r.answers[d.id]===d.answer).length;}
function scaleDefaults(){const b=biz();return{spend:'30000',cpc:String(Math.round(b.cpc*1.35)),cvr:String(Math.max(.1,b.cvr*.8)),close:String(b.close),aov:String(b.aov),margin:String(b.margin),capacity:state.business==='shop'?'100':'10'};}
function scaleInputs(){return{...scaleDefaults(),...optimizationRecord().scale};}
function scaleModel(raw,business=state.business){if(!CAMPAIGN_CASES[business])return null;const v={};for(const field of SCALE_FIELDS){const x=raw[field];if((typeof x!=='string'&&typeof x!=='number')||String(x).trim()===''||!Number.isFinite(Number(x)))return null;v[field]=Number(x);}if(v.spend<0||v.spend>1e9||v.cpc<=0||v.cpc>1e9||v.aov<0||v.aov>1e9||v.capacity<0||v.capacity>1e9||!Number.isInteger(v.capacity)||[v.cvr,v.close,v.margin].some(x=>x<0||x>100))return null;const base=CAMPAIGN_CASES[business],clicks=v.spend/v.cpc,leads=clicks*v.cvr/100,demand=leads*v.close/100,delivered=Math.min(demand,v.capacity),revenue=delivered*v.aov,added=revenue*v.margin/100-v.spend,baseContribution=base.revenue*base.margin/100-base.spend;return{clicks,leads,demand,delivered,unserved:Math.max(0,demand-delivered),revenue,added,baseContribution,totalContribution:baseContribution+added,addedCAC:delivered>0?v.spend/delivered:null,totalSpend:base.spend+v.spend,baseSpend:base.spend,capacityLimited:demand>v.capacity};}
function reviewTestPlan(p){const issues=[];for(const f of ['hypothesis','change','primary','guardrail','evidence','rollback','owner'])if(typeof p[f]!=='string'||!p[f].trim())issues.push(f);const lag=Number(p.lagDays),read=Number(p.readoutDays),split=Number(p.split);if(p.lagDays===undefined||String(p.lagDays).trim()===''||!Number.isFinite(lag)||lag<0||lag>365)issues.push('lagDays');if(p.readoutDays===undefined||String(p.readoutDays).trim()===''||!Number.isFinite(read)||read<0||read>730||Number.isFinite(lag)&&read<lag)issues.push('readoutDays');if(p.split===undefined||String(p.split).trim()===''||!Number.isFinite(split)||split<=0||split>=100)issues.push('split');return [...new Set(issues)];}
function optimizePage(){return `${heading('SEARCH ADS · OPTIMIZE WITH EVIDENCE',U('Zyada spend se pehle hisaab.','Do the maths before more spend.'),U('6 decisions, marginal scaling model aur exportable experiment plan.','Six decisions, a marginal scaling model and an exportable experiment plan.'))}<div class="note">${U('Fictional teaching data aur assumptions. Ye Google forecast, statistical significance test ya live campaign control nahi. Actual demand, auctions, delay aur customer capacity results badal saktay hain.','Fictional teaching data and assumptions. This is not a Google forecast, significance test or live campaign control. Demand, auctions, lag and customer capacity can change actual results.')}</div><div class="section-heading" style="margin-top:22px"><span class="tag">${optimizationSolved()}/6 ${U('decision checks','decision checks')}</span><select class="lang" id="opt-business" aria-label="Optimization business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div><div class="tabs">${[['decisions',P('Review decisions','Review decisions')],['scale',P('Budget barha kar dekho','Explore added spend')],['plan',P('Apna test design karo','Design your test')]].map(([k,n])=>`<button data-opt-tab="${k}" class="${optTab===k?'active':''}">${esc(t(n))}</button>`).join('')}</div>${optTab==='decisions'?optimizationDecisions():optTab==='scale'?scalingPage():testPlanPage()}${footer()}`;}
function optimizationDecisions(){const d=OPT_DECISIONS[optDecision],a=optimizationRecord().answers[d.id];return `<div class="journey-layout"><aside class="card journey-menu">${OPT_DECISIONS.map((x,i)=>`<button class="guide-step ${optDecision===i?'active':''}" data-opt-decision="${i}"><span>${optimizationRecord().answers[x.id]===x.answer?'✓':'○'}</span>${esc(t(x.title))}</button>`).join('')}</aside><article class="card"><div class="eyebrow">FICTIONAL DECISION ${optDecision+1} / 6</div><h2>${esc(t(d.title))}</h2><div class="example"><p>${esc(t(d.evidence))}</p></div><h3>${esc(t(d.question))}</h3><div class="quiz-options">${d.options.map((x,i)=>`<button class="option ${a===i?(i===d.answer?'correct':'wrong'):''}" data-opt-answer="${i}">${String.fromCharCode(65+i)}. ${esc(t(x))}</button>`).join('')}</div>${a!==undefined?`<div class="feedback ${a===d.answer?'':'error'}" role="status">${a===d.answer?'✓':U('Dobara socho.','Reconsider.')} ${esc(t(d.why))}</div>`:''}<div class="action-row"><button class="btn light" id="opt-next">${U('Agla decision','Next decision')} →</button><button class="btn light" data-opt-tab="scale">${U('Scaling khud try karo','Try scaling yourself')}</button></div>${sourceLinks(d.source)}</article></div>`;}
function scalingPage(){const v=scaleInputs();return `<div class="cols"><section class="card"><div class="eyebrow">ASSUMPTION MODEL · NOT A FORECAST</div><h2>${U('Sirf extra spend ka result dekho.','Look at the added spend itself.')}</h2><p>${U('Existing mature case baseline hai. Neechay additional test period ki assumptions dalo; purana average automatically reuse nahi hota. Capacity additional customers ki limit hai; spend phir bhi incur hota hai.','The existing mature case is the baseline. Enter assumptions for an additional test period; the historical average is not automatically reused. Capacity limits additional customers served, while the spend is still incurred.')}</p><div class="form-grid">${[
['spend',P('Extra period spend (Rs)','Additional period spend (Rs)')],['cpc',P('Extra traffic ka assumed CPC (Rs)','Assumed CPC of extra traffic (Rs)')],['cvr',P('Extra clicks → lead/order (%)','Extra clicks → lead/order (%)')],['close',P('Lead/order → paid customer (%)','Lead/order → paid customer (%)')],['aov',P('Revenue per served customer (Rs)','Revenue per served customer (Rs)')],['margin',P('Variable costs ke baad contribution (%)','Contribution after variable costs (%)')],['capacity',P('Extra customers serve karne ki capacity','Capacity for additional customers')]
].map(([f,label])=>`<label class="field">${esc(t(label))}<input id="scale-${f}" data-scale="${f}" type="number" value="${esc(v[f])}" min="${f==='cpc'?'.01':'0'}" ${['cvr','close','margin'].includes(f)?'max="100"':''} step="${f==='capacity'?'1':'any'}"></label>`).join('')}</div><div class="action-row"><button class="btn light" id="scale-reset">${U('Fictional defaults wapas lao','Restore fictional defaults')}</button><button class="btn light" data-opt-tab="plan">${U('Test plan banao','Build a test plan')} →</button></div><details class="source-details"><summary>${U('Formula aur limits','Formula and limitations')}</summary><div class="formula">Extra clicks = spend ÷ assumed CPC<br>Demand = clicks × lead/order rate × close rate<br>Served = min(demand, extra capacity)<br>Added contribution after ads = served × revenue/customer × margin − extra spend</div><p>${U('Fractional customers expected values hain. Fixed overhead, taxes, refunds, repeat value, auction response aur causal incrementality model nahi hotay. Same-period comparable baseline assume hota hai.','Fractional customers are expected values. Fixed overhead, taxes, refunds, repeat value, auction response and causal incrementality are not modelled. The baseline assumes comparable periods.')}</p>${sourceLinks(['bidtargets','measurement'])}</details></section><aside class="card" id="scale-result" aria-live="polite">${scaleResults(v)}</aside></div>`;}
function scaleResults(raw){const r=scaleModel(raw);if(!r)return `<div class="feedback error">${U('Valid numbers dalo: CPC > 0, rates 0–100%, capacity non-negative whole number. Blank zero nahi hota.','Enter valid numbers: CPC > 0, rates 0–100%, capacity a non-negative whole number. A blank is not zero.')}</div>`;return `<div class="eyebrow">${esc(t(biz().name))} · FICTIONAL CASE + ASSUMPTIONS</div><h3>${U('Average aur extra result alag hain.','The average and added result differ.')}</h3><div class="metrics">${metric('Existing contribution after ads',money(r.baseContribution),'Before fixed overhead')}${metric('Added contribution after ads',money(r.added),'From assumed extra spend')}${metric('Combined contribution after ads',money(r.totalContribution),'Baseline + modeled addition')}${metric('Expected additional customers',num(r.delivered,2),'After capacity limit')}${metric('Modeled additional CAC',r.addedCAC===null?'—':money(r.addedCAC),'Extra spend ÷ customers served')}${metric('Expected unserved demand',num(r.unserved,2),'Acquired demand above capacity')}</div><div class="feedback ${r.added<0?'error':''}">${r.added<0?U('Is assumption set mein extra spend negative contribution deta hai. Combined total positive ho tab bhi extra spend ka loss chhup sakta hai.','Under these assumptions, added spend loses contribution. A positive combined total can hide the added loss.'):U('Is assumption set mein added contribution non-negative hai. Ye real scale recommendation ya guaranteed result nahi; measurement, demand aur constraints verify karo.','Added contribution is non-negative under these assumptions. This is not a scaling recommendation or guarantee; verify measurement, demand and constraints.')}</div>${r.capacityLimited?`<p>${U('Capacity bottleneck: extra demand mein se kuch serve nahi ho sakti, jab ke model poora ad spend charge karta hai.','Capacity bottleneck: some acquired demand cannot be served, while the model charges the full ad spend.')}</p>`:''}`;}
const TEST_LABELS={hypothesis:P('Hypothesis: kis wajah se result improve hoga?','Hypothesis: why should the result improve?'),change:P('Ek defined change','One defined change'),primary:P('Primary business metric + baseline','Primary business metric + baseline'),guardrail:P('Kya kharab nahi hona chahiye?','What must not worsen?'),evidence:P('Required evidence / minimum effect / uncertainty review','Required evidence / minimum effect / uncertainty review'),lagDays:P('Known conversion maturity delay (days)','Known conversion maturity delay (days)'),readoutDays:P('Last included click ke baad final readout delay (days)','Final readout delay after the last included click (days)'),split:P('Proposed test traffic share (%)','Proposed test traffic share (%)'),rollback:P('Stop / rollback condition','Stop / rollback condition'),owner:P('Owner aur review responsibility','Owner and review responsibility')};
function testPlanPage(){const p=optimizationRecord().plan;return `<section class="card"><div class="eyebrow">PLAN ONLY · NO LIVE EXPERIMENT CREATED</div><h2>${U('Result dekhne se pehle rules likho.','Write the rules before seeing results.')}</h2><p>${U('Business example ke liye fictional plan likho. Traffic split aur eligibility actual experiment type mein verify honi hai; ye form koi universal split enforce nahi karta. Review delay ko traffic collection duration se alag samjho.','Write a fictional plan for the selected business. Verify traffic splitting and eligibility for the actual experiment type. Distinguish readout delay from traffic collection duration.')}</p><div class="example"><p>${state.business==='shop'?U('Example: product-page size guidance test karo; primary net paid-order contribution, guardrail returns aur checkout errors.','Example: test size guidance on the product page; primary metric net paid-order contribution, guardrails returns and checkout errors.'):state.business==='b2b'?U('Example: qualification copy test karo; primary qualified-opportunity cost, guardrail won-client quality. Long sales delay account karo.','Example: test qualification copy; primary metric qualified-opportunity cost, guardrail won-client quality. Account for the long sales delay.'):U('Example: booking form test karo; primary qualified booking cost, guardrail spam aur technician capacity.','Example: test the booking form; primary metric qualified booking cost, guardrails spam and technician capacity.')}</p></div><div class="form-grid">${TEST_FIELDS.map(f=>`<label class="field">${esc(t(TEST_LABELS[f]))}${['lagDays','readoutDays','split'].includes(f)?`<input type="number" data-test-plan="${f}" value="${esc(p[f]??'')}" min="0" step="any">`:`<textarea data-test-plan="${f}" maxlength="5000" rows="3">${esc(p[f]||'')}</textarea>`}</label>`).join('')}</div><small id="test-save" role="status">${U('Autosaved in this browser. Sirf fictional practice data likho.','Autosaved in this browser. Use fictional practice data only.')}</small><div class="action-row"><button class="btn" id="test-review">${U('Plan ki missing cheezen check karo','Check the plan for missing items')}</button><button class="btn light" id="test-export">${U('Plan download','Download plan')}</button></div><div id="test-feedback" aria-live="polite"></div><details class="source-details"><summary>${U('Real experiment aur interpretation','Real experiments and interpretation')}</summary><p>${U('Google experiment results, confidence intervals, lag, business significance aur concurrent changes review karo. Is checklist ka pass hona sample size, causality ya statistical significance prove nahi karta. Before/after report ko controlled experiment ka substitute mat samjho.','Review experiment results, uncertainty, lag, business significance and concurrent changes. Passing this checklist does not establish sample adequacy, causality or statistical significance. A before/after report is not a controlled experiment.')}</p>${sourceLinks(['experimentspage','lag'])}</details></section>`;}
function bindOptimize(){$('#opt-business').onchange=e=>{state.business=e.target.value;save();render();};$$('[data-opt-tab]').forEach(b=>b.onclick=()=>{optTab=b.dataset.optTab;render();});$$('[data-opt-decision]').forEach(b=>b.onclick=()=>{optDecision=+b.dataset.optDecision;render();});$$('[data-opt-answer]').forEach(b=>b.onclick=()=>{optimizationRecord().answers[OPT_DECISIONS[optDecision].id]=+b.dataset.optAnswer;save();const y=window.scrollY;render();window.scrollTo(0,y);});const next=$('#opt-next');if(next)next.onclick=()=>{optDecision=(optDecision+1)%OPT_DECISIONS.length;render();};$$('[data-scale]').forEach(el=>el.oninput=()=>{optimizationRecord().scale[el.dataset.scale]=el.value;save();$('#scale-result').innerHTML=scaleResults(scaleInputs());});const reset=$('#scale-reset');if(reset)reset.onclick=()=>{optimizationRecord().scale={};save();render();};$$('[data-test-plan]').forEach(el=>el.oninput=()=>{optimizationRecord().plan[el.dataset.testPlan]=el.value.slice(0,5000);save();$('#test-save').textContent=storageOK?U('Saved in this browser','Saved in this browser'):U('Storage unavailable; plan download karo','Storage unavailable; download the plan');const feedback=$('#test-feedback');if(feedback)feedback.innerHTML='';});const review=$('#test-review');if(review)review.onclick=()=>{const issues=reviewTestPlan(optimizationRecord().plan);$('#test-feedback').innerHTML=`<div class="feedback ${issues.length?'error':''}" style="margin-top:20px">${issues.length?U('Missing/invalid fields: ','Missing/invalid fields: ')+issues.map(k=>esc(t(TEST_LABELS[k]))).join(' · '):U('Planning fields complete. Experiment eligibility, evidence adequacy aur live results independently verify karo.','Planning fields complete. Independently verify eligibility, evidence adequacy and live results.')}</div>`;};const ex=$('#test-export');if(ex)ex.onclick=()=>download('ads-asaan-'+state.business+'-experiment-plan.json',{simulation:true,business:biz().name[1],plan:optimizationRecord().plan,planningIssues:reviewTestPlan(optimizationRecord().plan),notice:'A planning checklist, not a live experiment, sample-size calculation or significance test.'});}
